import{_ as a,o as n,c as e,a5 as t}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"67. Time and Clock APIs","description":"The Little Book of C — 67. Time and Clock APIs","frontmatter":{"title":"67. Time and Clock APIs","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Working Close to the System"],"description":"The Little Book of C — 67. Time and Clock APIs","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":67,"sidebarWeight":67,"lang":"en-US","alternateEn":"/posts/c教程/en-US/07-Working Close to the System/067-Time and Clock APIs","alternateZh":"/posts/c教程/zh-CN/07-贴近系统/067-Time and Clock APIs"},"headers":[],"relativePath":"posts/c教程/en-US/07-Working Close to the System/067-Time and Clock APIs.md","filePath":"posts/c教程/en-US/07-Working Close to the System/067-Time and Clock APIs.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/07-Working Close to the System/067-Time and Clock APIs.md"};function p(l,s,o,c,d,r){return n(),e("div",null,[...s[0]||(s[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/07-贴近系统/067-Time and Clock APIs)</p><p>Time is one of the simplest things humans understand, and one of the trickiest things for computers to handle correctly. In C, time is represented in seconds since the Unix epoch (Jan 1, 1970), and you can work with it at various levels: wall-clock time, process time, and high-precision timers.</p><p>Let’s explore how to get, format, and measure time in C.</p><h4 id="step-1-the-basics-time" tabindex="-1">Step 1. The Basics: time() <a class="header-anchor" href="#step-1-the-basics-time" aria-label="Permalink to &quot;Step 1. The Basics: time()&quot;">​</a></h4><p>The simplest way to get the current time is with the<code>time()</code> function.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;time.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    time_t now = time(NULL);</span></span>
<span class="line"><span>    printf(&quot;Seconds since epoch: %ld\\n&quot;, now);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Seconds since epoch: 1739709201</span></span></code></pre></div><p>That’s the number of seconds since 1970-01-01 00:00:00 UTC.</p><h4 id="step-2-converting-to-human-readable-format" tabindex="-1">Step 2. Converting to Human-Readable Format <a class="header-anchor" href="#step-2-converting-to-human-readable-format" aria-label="Permalink to &quot;Step 2. Converting to Human-Readable Format&quot;">​</a></h4><p>You can convert<code>time_t</code> into a calendar date using<code>localtime()</code> or<code>gmtime()</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;time.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    time_t now = time(NULL);</span></span>
<span class="line"><span>    struct tm *t = localtime(&amp;now);</span></span>
<span class="line"><span>    printf(&quot;Local time: %02d-%02d-%04d %02d:%02d:%02d\\n&quot;,</span></span>
<span class="line"><span>           t-&gt;tm_mday, t-&gt;tm_mon + 1, t-&gt;tm_year + 1900,</span></span>
<span class="line"><span>           t-&gt;tm_hour, t-&gt;tm_min, t-&gt;tm_sec);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Local time: 16-10-2025 09:32:10</span></span></code></pre></div><h4 id="step-3-formatting-dates-with-strftime" tabindex="-1">Step 3. Formatting Dates with strftime() <a class="header-anchor" href="#step-3-formatting-dates-with-strftime" aria-label="Permalink to &quot;Step 3. Formatting Dates with strftime()&quot;">​</a></h4><p><code>strftime()</code> lets you format time into a string safely.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;time.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    char buf[100];</span></span>
<span class="line"><span>    time_t now = time(NULL);</span></span>
<span class="line"><span>    struct tm *t = localtime(&amp;now);</span></span>
<span class="line"><span>    strftime(buf, sizeof(buf), &quot;%Y-%m-%d %H:%M:%S&quot;, t);</span></span>
<span class="line"><span>    printf(&quot;Formatted: %s\\n&quot;, buf);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Formatted: 2025-10-16 09:32:10</span></span></code></pre></div><h4 id="step-4-measuring-elapsed-time" tabindex="-1">Step 4. Measuring Elapsed Time <a class="header-anchor" href="#step-4-measuring-elapsed-time" aria-label="Permalink to &quot;Step 4. Measuring Elapsed Time&quot;">​</a></h4><p>To measure how long something takes, use<code>clock()</code> from<code>&lt;time.h&gt;</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;time.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    clock_t start = clock();</span></span>
<span class="line"><span>    for (volatile long i = 0; i &lt; 100000000; i++);</span></span>
<span class="line"><span>    clock_t end = clock();</span></span>
<span class="line"><span>    double seconds = (double)(end - start) / CLOCKS_PER_SEC;</span></span>
<span class="line"><span>    printf(&quot;Elapsed time: %.3f seconds\\n&quot;, seconds);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Elapsed time: 0.520 seconds</span></span></code></pre></div><p><code>clock()</code> measures CPU time, not real elapsed time, so it excludes time spent waiting for I/O or sleeping.</p><h4 id="step-5-high-resolution-timing-with-clock-gettime" tabindex="-1">Step 5. High-Resolution Timing with clock_gettime() <a class="header-anchor" href="#step-5-high-resolution-timing-with-clock-gettime" aria-label="Permalink to &quot;Step 5. High-Resolution Timing with clock_gettime()&quot;">​</a></h4><p>For precise measurements, use<code>clock_gettime()</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;time.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    struct timespec start, end;</span></span>
<span class="line"><span>    clock_gettime(CLOCK_MONOTONIC, &amp;start);</span></span>
<span class="line"><span>    for (volatile long i = 0; i &lt; 100000000; i++);</span></span>
<span class="line"><span>    clock_gettime(CLOCK_MONOTONIC, &amp;end);</span></span>
<span class="line"><span>    double elapsed = (end.tv_sec - start.tv_sec)</span></span>
<span class="line"><span>                   + (end.tv_nsec - start.tv_nsec) / 1e9;</span></span>
<span class="line"><span>    printf(&quot;Elapsed: %.6f seconds\\n&quot;, elapsed);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Elapsed: 0.515421 seconds</span></span></code></pre></div><p>This measures real elapsed time, immune to system clock changes.</p><h4 id="step-6-sleeping-for-a-duration" tabindex="-1">Step 6. Sleeping for a Duration <a class="header-anchor" href="#step-6-sleeping-for-a-duration" aria-label="Permalink to &quot;Step 6. Sleeping for a Duration&quot;">​</a></h4><p>You can make your program pause using<code>sleep()</code> or<code>nanosleep()</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Sleeping for 2 seconds...\\n&quot;);</span></span>
<span class="line"><span>    sleep(2);</span></span>
<span class="line"><span>    printf(&quot;Awake!\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>For sub-second precision:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;time.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    struct timespec ts = {0, 500000000}; // 0.5 seconds</span></span>
<span class="line"><span>    nanosleep(&amp;ts, NULL);</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="step-7-getting-utc-and-local-time-zones" tabindex="-1">Step 7. Getting UTC and Local Time Zones <a class="header-anchor" href="#step-7-getting-utc-and-local-time-zones" aria-label="Permalink to &quot;Step 7. Getting UTC and Local Time Zones&quot;">​</a></h4><p><code>gmtime()</code> gives you UTC, while<code>localtime()</code> converts to your system’s timezone.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>time_t now = time(NULL);</span></span>
<span class="line"><span>printf(&quot;UTC:   %s&quot;, asctime(gmtime(&amp;now)));</span></span>
<span class="line"><span>printf(&quot;Local: %s&quot;, asctime(localtime(&amp;now)));</span></span></code></pre></div><p>You can change timezone behavior via the<code>TZ</code> environment variable and<code>tzset()</code>.</p><h4 id="step-8-process-time-and-resource-usage" tabindex="-1">Step 8. Process Time and Resource Usage <a class="header-anchor" href="#step-8-process-time-and-resource-usage" aria-label="Permalink to &quot;Step 8. Process Time and Resource Usage&quot;">​</a></h4><p>You can inspect how much CPU time your program used with<code>getrusage()</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;sys/resource.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    struct rusage usage;</span></span>
<span class="line"><span>    getrusage(RUSAGE_SELF, &amp;usage);</span></span>
<span class="line"><span>    printf(&quot;User CPU time: %ld.%06lds\\n&quot;,</span></span>
<span class="line"><span>           usage.ru_utime.tv_sec, usage.ru_utime.tv_usec);</span></span>
<span class="line"><span>    printf(&quot;System CPU time: %ld.%06lds\\n&quot;,</span></span>
<span class="line"><span>           usage.ru_stime.tv_sec, usage.ru_stime.tv_usec);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This is how profilers measure CPU consumption.</p><h4 id="step-9-time-differences" tabindex="-1">Step 9. Time Differences <a class="header-anchor" href="#step-9-time-differences" aria-label="Permalink to &quot;Step 9. Time Differences&quot;">​</a></h4><p>You can subtract two<code>time_t</code> values using<code>difftime()</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;time.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    time_t start = time(NULL);</span></span>
<span class="line"><span>    sleep(2);</span></span>
<span class="line"><span>    time_t end = time(NULL);</span></span>
<span class="line"><span>    printf(&quot;Elapsed: %.0f seconds\\n&quot;, difftime(end, start));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Elapsed: 2 seconds</span></span></code></pre></div><h4 id="step-10-tiny-code-countdown-timer" tabindex="-1">Step 10. Tiny Code: Countdown Timer <a class="header-anchor" href="#step-10-tiny-code-countdown-timer" aria-label="Permalink to &quot;Step 10. Tiny Code: Countdown Timer&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    for (int i = 5; i &gt; 0; i--) {</span></span>
<span class="line"><span>        printf(&quot;%d...\\n&quot;, i);</span></span>
<span class="line"><span>        sleep(1);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    printf(&quot;Time&#39;s up!\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>5...</span></span>
<span class="line"><span>4...</span></span>
<span class="line"><span>3...</span></span>
<span class="line"><span>2...</span></span>
<span class="line"><span>1...</span></span>
<span class="line"><span>Time&#39;s up!</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Time functions are critical in:</p><ul><li>Logging and timestamps</li><li>Benchmarking and profiling</li><li>Scheduling events</li><li>Measuring performance of algorithms</li><li>Synchronizing distributed systems</li></ul><p>Every systems program eventually needs accurate, reliable time measurement, and C gives you all the low-level tools to do it efficiently.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Print the current date in ISO 8601 format.</li><li>Measure how long it takes to read a large file.</li><li>Build a stopwatch that measures elapsed time with<code>clock_gettime()</code>.</li><li>Make a countdown timer that updates in place on the terminal.</li><li>Display both UTC and local time, formatted nicely.</li></ol><p>Next, you’ll learn how to access and modify environment variables, another key part of how Unix programs communicate with their runtime environment.</p>`,60)])])}const m=a(i,[["render",p]]);export{h as __pageData,m as default};
